# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - January to April, from saints_daily_en_1.py
DATA = [
    ("January 1", "Mary, Mother of God", "Meryem, Tanrı'nın Anası", "Kilise yıla, 431'de Efes'te onaylanan en eski Meryem unvanıyla, Theotokos ('Tanrı'yı doğuran') ile başlar. Oğlu gerçekten Tanrı olduğu için Meryem gerçekten Tanrı'nın Anası'dır.", "Anneler, Kilise, barış"),
    ("January 3", "Most Holy Name of Jesus", "İsa'nın Kutsal Adı", "'Tanrı kurtarır' anlamına gelen İsa adına duyulan bağlılık bayramı. Sienalı Aziz Bernardino ve Fransiskenler, Kutsal Ad'ı sevgi ve saygıyla anma geleneğini yaydı.", "Huzur arayanlar, vaizler"),
    ("January 5", "Saint John Neumann", "Aziz John Neumann", "Bohemya doğumlu Redemptorist (1811-1860); Philadelphia piskoposu oldu. Amerika Birleşik Devletleri'nde ilk Katolik piskoposluk okul sistemini kurdu ve göçmenlere birkaç dilde hizmet etti.", "Katolik okulları, göçmenler"),
    ("January 7", "Saint Raymond of Penyafort", "Aziz Raymond of Penyafort", "İspanyol Dominikan kilise hukukçusu (yaklaşık 1175-1275). Kilise kararlarını tek bir derlemede topladı ve Aziz Peter Nolasco'nun tutsakları kurtarmasına yardım etti. İtirafta gösterdiği yumuşaklıkla tanınırdı.", "Kilise hukukçuları, günah çıkarıcılar"),
    ("January 8", "Saint Severinus of Noricum", "Noricumlu Aziz Severinus", "Tuna boyunda yaşayan beşinci yüzyıl keşişi ve misyoneri. Roma yönetiminin çöküşü sırasında açları doyurdu, tutsakları kurtardı, halka teselli verdi. Romalılar da barbarlar da ona güvendi.", "Savaş ve kıtlıkta çaresiz kalanlar"),
    ("January 9", "Saint Adrian of Canterbury", "Canterbury'li Aziz Adrian", "Başpiskopos Theodore ile İngiltere'ye gelen Kuzey Afrikalı başrahip (ö. 710). Canterbury'deki okulunda Latince, Yunanca, hukuk ve Kutsal Kitap öğretildi; İngiliz Kilisesi'ni kuşaklar boyunca şekillendirdi.", "Öğretmenler, bilginler"),
    ("January 10", "Saint Gregory of Nyssa", "Nyssalı Aziz Gregory", "Piskopos ve ilahiyatçı (yaklaşık 335-395), Aziz Basil'in kardeşi ve üç Kapadokyalı Baba'dan biri. İstanbul'da Teslis'i savundu; dua ve ruhun Tanrı'ya yükselişi üzerine derin yazılar yazdı.", "İlahiyatçılar, dua edenler"),
    ("January 11", "Pope Saint Hyginus", "Papa Aziz Hyginus", "İkinci yüzyılda Roma piskoposu. Kiliseyi yanlış öğretiş ve zulüm dönemlerinden geçirdi. Gelenek onu, havarilerden devralınan imanı savunan bir şehit olarak onurlandırır.", "Sağlam öğretiyi savunanlar"),
    ("January 12", "Saint Marguerite Bourgeoys", "Aziz Marguerite Bourgeoys", "Fransız doğumlu öğretmen (1620-1700). Montreal'e gitti ve çocukları eğitmek için Notre Dame Cemaati'ni kurdu. Kanada'nın kurucu annelerinden biri ve pratik sevgi örneğidir.", "Öğretmenler, göçmenler, Kanada"),
    ("January 13", "Saint Hilary of Poitiers", "Poitiers'li Aziz Hilary", "Galya piskoposu (yaklaşık 310-367). İmparator tarafından sürgüne gönderilse de Ariusçuluğa direndi. Teslis üzerine yazıları ve ilahileriyle Kilise Doktoru unvanını aldı.", "İmanı savunanlar, bel ağrısı çekenler"),
    ("January 15", "Saint Paul the Hermit", "Münzevi Aziz Paul", "Mısırlı münzevi (ö. yaklaşık 342); çölde yaşayan ilk Hıristiyan keşiş sayılır. Gelenek, Aziz Anthony'nin onu ziyaret edip gömdüğünü, bir kuzgunun her gün mağarasına ekmek getirdiğini anlatır.", "Münzeviler, yalnızlık arayanlar"),
    ("January 16", "Saint Berard and Companions", "Aziz Berard ve Arkadaşları", "1220'de Fas'ta vaaz verirken şehit edilen beş Fransiskan. Tanıklıkları, Padovalı Aziz Anthony'yi Fransiskan tarikatına katılmaya ve Afrika'ya gitmeye yöneltti.", "Misyonerler, şehitler"),
    ("January 18", "Saint Prisca", "Aziz Prisca", "Üçüncü yüzyılda Mesih uğruna ölen genç bir Romalı kadın. Aventin Tepesi'ndeki kilisesi Roma'nın en eski kiliselerinden biridir; erken dönem şehitlerinin en sevileni arasındadır.", "Gençler, şehitler"),
    ("January 19", "Saint Canute of Denmark", "Danimarkalı Aziz Canute", "Kiliseyi ve yoksulları korumak, adaleti güçlendirmek için çalışan Danimarka kralı (ö. 1086). Odense'de sunakta öldürüldü; ülkesinin şehit koruyucusu olarak anılır.", "Danimarka, hükümdarlar, haksızlığa uğrayanlar"),
    ("January 22", "Saint Vincent of Saragossa", "Saragossa'lı Aziz Vincent", "304'te Diocletianus döneminde işkence görüp öldürülen İspanyol diyakoz; sonuna kadar sebat etti. Erken Kilise'nin en yaygın onurlandırılan şehitlerindendir.", "Diyakozlar, bağcılar, hapistekiler"),
    ("January 23", "Saint Marianne Cope", "Aziz Marianne Cope", "Almanya doğumlu Amerikalı Fransiskan rahibe (1838-1918). Molokai'de cüzzamlılara bakmak için Hawaii'ye gitti; otuz yıl korkusuzca hizmet etti. 2012'de aziz ilan edildi.", "Cüzzamlılar, bakıcılar, dışlanmışlar"),
    ("January 25", "The Conversion of Saint Paul", "Aziz Pavlus'un Dönüşümü", "Kilise, Şam yolunda Mesih'in zulmeden Saul'u uluslara havari yaptığı anı anar. Pavlus'un mektupları Yeni Antlaşma'nın büyük bir bölümünü oluşturur.", "Misyonerler, din değiştirenler, ilahiyatçılar"),
    ("January 26", "Saints Timothy and Titus", "Aziz Timoteos ve Aziz Titus", "Pavlus'un arkadaşları; Efes ve Girit'te piskopos oldular. Pavlus'un onlara yazdığı mektuplar, Kilise'ye gözetmenlik etmek ve sadık bir yaşam sürmek için rehberlik eder.", "Papazlar, piskoposlar, genç önderler"),
    ("January 27", "Saint Angela Merici", "Aziz Angela Merici", "Kızları eğitmek için Aziz Ursula Topluluğu'nu kuran İtalyan laik kadın (yaklaşık 1474-1540). Rahibeleri Ursulinler, Kilise'nin ilk kadın öğretmen tarikatı oldu.", "Öğretmenler, kız çocuklarını eğitenler"),
    ("January 29", "Saint Gildas the Wise", "Bilge Aziz Gildas", "Britanyalı keşiş ve yazar (yaklaşık 500-570). Britanya krallarına ve din adamlarına yönelttiği keskin ve dokunaklı tövbe çağrısıyla tanınır. Britanya ve Bretagne'de münzevi ve öğretmen olarak yaşadı.", "Tarihçiler, ıslah çağrısı yapanlar"),
    ("January 30", "Saint Hyacintha Mariscotti", "Aziz Hyacintha Mariscotti", "Dindarlıktan uzak başlayan ama hastalık ve duayla dönüşen İtalyan Fransiskan üçüncü tarikat üyesi (1585-1640). Son yıllarını Viterbo'nun yoksullarına ve hastalarına hizmetle geçirdi.", "Hastalar, tövbe edenler, yoksullar"),

    ("February 1", "Saint Brigid of Kildare", "Kildare'li Aziz Brigid", "Kildare manastırını kuran ve Aziz Patrick'in yanında İrlanda'nın koruyucusu olan İrlandalı başrahibe (yaklaşık 451-525). Yoksullara cömertliği ve herkese konukseverliğiyle anılır.", "İrlanda, süt işçileri, bilginler"),
    ("February 2", "The Presentation of the Lord", "Rab'bin Mabede Sunuluşu", "Noel'den kırk gün sonra Meryem ve Yusuf bebek İsa'yı Tapınak'a getirir; Simeon O'nu uluslar için bir ışık olarak selamlar. Mumlar kutsanır, bu yüzden bayrama Kandil Günü denir.", "Adanmış yaşam, aileler"),
    ("February 4", "Saint John de Britto", "Aziz John de Britto", "Güney Hindistan'da İncil'i paylaşmak için Hintli bir çileci gibi yaşayan Portekizli Cizvit (1647-1693). Bir prensi vaftiz ettiği için boynu vurulan şehit olarak anılır.", "Misyonerler, Hindistan"),
    ("February 5", "Saint Agatha", "Aziz Agatha", "Mesih'i inkâr etmeyi reddettiği için yaklaşık 251'de Katanya'da şehit edilen genç Sicilyalı kadın. İşkence altındaki cesareti onu en sevilen bakire şehitlerden biri yaptı. Bayramında ekmek kutsanır.", "Hemşireler, meme kanseri hastaları, çan dökümcüleri"),
    ("February 7", "Blessed Pius IX", "Mübarek Pius IX", "Kilise tarihinin doğrulanmış en uzun papalığına (1846-1878) sahip papa (1792-1878). Meryem'in Lekesiz Gebe Kalışı dogmasını ilan etti ve Birinci Vatikan Konsili'ni topladı.", "Papazlar, sınav dönemlerindeki Kilise"),
    ("February 9", "Saint Apollonia", "Aziz Apollonia", "249 dolaylarında bir zulüm sırasında dişleri kırılan ve Mesih'i inkâr etmektense ölümü seçen İskenderiyeli yaşlı kadın diyakoz. Diş ağrısına karşı anılır.", "Diş hekimleri, diş ağrısı çekenler"),
    ("February 12", "Saint Meletius of Antioch", "Antakyalı Aziz Meletius", "Ortodoks imanı yüzünden sürgün çeken ve İstanbul Konsili'ne başkanlık eden Antakya piskoposu (ö. 381). Kilise bölünmüşken gösterdiği yumuşaklıkla sevildi.", "Barış yapıcılar, piskoposlar"),
    ("February 13", "Saint Catherine de' Ricci", "Aziz Catherine de' Ricci", "On iki yıl boyunca her hafta Çile üzerine esrik tefekkürde bulunan Floransalı Dominikan rahibe (1522-1590). Aynı zamanda yetenekli bir yönetici, güvenilir danışman ve azizlerin dostuydu.", "Hastalar, mistikler"),
    ("February 15", "Saint Claude de la Colombière", "Aziz Claude de la Colombière", "Aziz Margaret Mary Alacoque'un ruhsal rehberi olan ve İsa'nın Kutsal Kalbi'ne bağlılığı yayan Fransız Cizvit (1641-1682). Kendi hayatını ilahi takdire emanet etti.", "Ruhsal rehberler, Kutsal Kalp'e bağlı olanlar"),
    ("February 16", "Saint Juliana of Nicomedia", "İzmitli Aziz Juliana", "Putperest bir görevliyle evlenmeyi ve imanından vazgeçmeyi reddettiği için yaklaşık 304'te şehit edilen genç kadın. Gelenek, hapsi ve işkenceyi sakin bir sabırla çektiğini anlatır.", "İmanından vazgeçmesi için baskı görenler"),
    ("February 17", "The Seven Holy Founders of the Servite Order", "Servit Tarikatı'nın Yedi Kutsal Kurucusu", "1233'te dua ve Acılı Meryem'e bağlılık içinde yaşamak için Monte Senario'ya çekilen yedi Floransalı tüccar. Meryem'in Hizmetkârları tarikatını kurdular.", "Dinî topluluklar, yas tutanlar"),
    ("February 19", "Saint Conrad of Piacenza", "Piacenza'lı Aziz Conrad", "Av sırasında kazara yangın çıkaran, sorumluluğu üstlenip servetini veren İtalyan soylu (1290-1351). Sicilya'da münzevi yaşadı; dua ve şifa armağanıyla tanındı.", "Münzeviler, fıtık çekenler, tövbe edenler"),
    ("February 20", "Saints Jacinta and Francisco Marto", "Aziz Jacinta ve Aziz Francisco Marto", "1917'de Fatima'da Meryem'i gören iki Portekizli çoban çocuk. Acılarını günahkârlar için sunduktan sonra 1919 ve 1920'de genç yaşta öldüler; 2017'de aziz ilan edildiler.", "Çocuklar, günahkârlar için dua edenler"),
    ("February 21", "Saint Peter Damian", "Aziz Peter Damian", "Din adamlarını ıslah etmeye çalışan ve yalın, tövbekâr bir dua yaşamını teşvik eden İtalyan keşiş ve kardinal (1007-1072). Yazıları nedeniyle Kilise Doktoru ilan edildi.", "Reformcular, keşişler, alçakgönüllülük arayanlar"),
    ("February 22", "The Chair of Saint Peter", "Aziz Petrus'un Makamı", "Petrus'un Kilise'nin çobanı olarak hizmetini kutlayan bayram. 'Boş makam', Petrus'a ve halefine emanet edilen öğretme yetkisini simgeler.", "Papa, Kilise'nin birliği"),
    ("February 24", "The Finding of the Head of Saint John the Baptist", "Vaftizci Yahya'nın Başının Bulunuşu", "Tövbe çağrısıyla Mesih'e yol hazırlayan öncü Yahya'nın baş kalıntısının bulunuşunu anan bayram.", "Tövbe edenler, vaizler"),
    ("February 25", "Saint Walburga", "Aziz Walburga", "Kardeşleriyle Almanya'ya gidip Aziz Boniface'a yardım eden ve Heidenheim çift manastırına önderlik eden İngiliz başrahibe (yaklaşık 710-779). Şifa için anılır.", "Denizciler, ekinler, şifa arayanlar"),
    ("February 26", "Saint Porphyry of Gaza", "Gazzeli Aziz Porphyry", "Halkın çoğunun putperest kaldığı bir şehirde sebat eden Gazze piskoposu (yaklaşık 347-420). Sabırla din değiştirenler kazandı, piskoposluğunun yoksullarına baktı.", "Zor ortamlardaki papazlar"),
    ("February 28", "Pope Saint Hilarius", "Papa Aziz Hilarius", "461-468 arasında papa. Kilise'nin birliğini savundu, Kadıköy Konsili'nin öğretisini korudu ve çalkantılı yıllarda Roma'nın yoksullarına baktı.", "Kilise birliğinin savunucuları"),
    ("February 29", "Saint Oswald of Worcester", "Worcester'lı Aziz Oswald", "İngiltere'de manastır yaşamının yenilenmesine yardım eden, Ramsey Manastırı'nı kuran York başpiskoposu (ö. 992). Alçakgönüllülüğü ve yoksullara ilgisiyle sevildi.", "Keşişler, reformcular, yoksullar"),

    ("March 1", "Saint David of Wales", "Galli Aziz David", "Galler boyunca manastırlar kuran, sade ve dua dolu yaşayan altıncı yüzyıl piskoposu ve başrahibi. Son sözü, 'Sevinçli olun, imanı koruyun', bugün de Galler'de anılır.", "Galler, şairler, sevinç arayanlar"),
    ("March 2", "Saint Chad of Lichfield", "Lichfield'li Aziz Chad", "Aziz Aidan'ın öğrencisi, vaaz vermek için kırsalı yürüyerek dolaşan yedinci yüzyıl İngiliz piskoposu. Lichfield piskoposu olarak alçakgönüllü hizmet etti ve sürüsünce sevildi.", "Misyonerler, uzun yollar yürüyenler"),
    ("March 4", "Saint Casimir of Poland", "Polonyalı Aziz Casimir", "Servetini yoksullara veren, güç yerine duayı seçen, bekâreti ve sade yaşamı benimseyen Polonyalı prens (1458-1484). 25 yaşında hastalıktan öldü; Polonya ve Litvanya'nın koruyucusudur.", "Gençler, Polonya, Litvanya"),
    ("March 5", "Saint Piran of Cornwall", "Cornwall'lı Aziz Piran", "Cornwall'a yerleşip halka çiftçiliği ve Mesih'i sevmeyi öğreten İrlanda doğumlu başrahip (ö. yaklaşık 480). Gelenek, kalay eritmeyi yeniden keşfettiğini söyler. Cornwall'ın koruyucusu sayılır.", "Cornwall, kalay madencileri"),
    ("March 6", "Saint Colette", "Aziz Colette", "Tarikatını ıslah ederek Aziz Clare'in katı yoksulluğunu yeniden canlandıran ve Avrupa'da pek çok manastır kuran Fransız Fakir Clare rahibesi (1381-1447).", "Reformcular, Kilise'de yenilenme arayanlar"),
    ("March 9", "Saint Frances of Rome", "Romalı Aziz Frances", "Veba ve savaş sırasında yoksullara ve hastalara bakan, bir adanmış topluluk kuran Romalı soylu kadın (1384-1440). Koruyucu meleğinin hep gözünün önünde olduğu söylenir.", "Eşler, dullar, sürücüler"),
    ("March 10", "Saint John Ogilvie", "Aziz John Ogilvie", "Düşmanca bir İskoçya'ya dönüp Katoliklere gizlice hizmet eden İskoç Cizvit (1579-1615). Tutuklandı ve Glasgow'da asıldı; Reform sonrası İskoçya'nın tek aziz ilan edilen kişisidir.", "İskoçya, vicdanı için acı çekenler"),
    ("March 11", "Saint Eulogius of Cordoba", "Kurtubalı Aziz Eulogius", "Mağribi İspanya'da zulüm gören Hıristiyanları cesaretlendiren rahip ve yazar. Hıristiyanlığa geçen genç bir kadını barındırdığı için 859'da başı kesildi.", "Zulüm gören Hıristiyanlar, yazarlar"),
    ("March 12", "Saint Maximilian of Tebessa", "Tebessa'lı Aziz Maximilian", "295'te imanı nedeniyle askerliği reddeden genç Kuzey Afrikalı. Roma valisi onu ölüme mahkûm etti; idama sevinçle yürüdü.", "Vicdani retçiler"),
    ("March 13", "Saint Euphrasia", "Aziz Euphrasia", "Mısır'daki bir manastırda itaat ve oruç dolu hizmet hayatı yaşayan beşinci yüzyıl bakiresi. Alçakgönüllülüğü ve yumuşaklığıyla saygı gördü.", "Sadelik arayanlar"),
    ("March 14", "Saint Matilda of Ringelheim", "Ringelheim'lı Aziz Matilda", "İmparator Büyük Otto'nun annesi, Almanya kraliçesi (yaklaşık 895-968). Dul kalınca kendini hayır işlerine ve duaya adadı, manastırlar kurdu, yoksullara baktı.", "Dullar, kraliçeler, kalabalık aileler"),
    ("March 15", "Saint Louise de Marillac", "Aziz Louise de Marillac", "Aziz Vincent de Paul ile Sevgi Kızları'nı kuran Fransız dul (1591-1660); rahibelerine yoksulda ve hastada Mesih'i görmeyi öğretti.", "Sosyal hizmet uzmanları, dullar"),
    ("March 16", "Saint Heribert of Cologne", "Kölnlü Aziz Heribert", "III. Otto'nun şansölyesi olan Köln başpiskoposu (yaklaşık 970-1021). Adaleti, yoksullara cömertliği ve duayla bir kuraklığı sona erdirmesiyle tanınır.", "Yağmur, otorite sahipleri"),
    ("March 20", "Saint Cuthbert of Lindisfarne", "Lindisfarne'li Aziz Cuthbert", "Tepelerde yoksullara öğretip sonra Farne Adası'nda münzevi yaşayan Northumbria'lı keşiş ve piskopos (yaklaşık 634-687). Cesedini keşişler kuzey İngiltere'de taşıdı.", "Kuzey İngiltere, çobanlar, denizciler"),
    ("March 22", "Saint Nicholas Owen", "Aziz Nicholas Owen", "Katoliklere yönelik zulüm sırasında rahipler için saklanma yerleri yapan İngiliz Cizvit kardeş (ö. 1606). Tutuklanıp işkenceyle öldürüldü, koruduklarını asla ele vermedi.", "Zanaatkârlar, kaçaklar, zulüm görenler"),
    ("March 23", "Saint Turibius of Mogrovejo", "Mogrovejolu Aziz Turibius", "Lima başpiskoposu olan İspanyol hukukçu (1538-1606). Devasa piskoposluğunu yürüyerek dolaştı, yerel dilleri öğrendi ve yerli halkı kötü muameleden korudu.", "Latin Amerikalı piskoposlar, yoksullara hizmet edenler"),
    ("March 24", "Saint Oscar Romero", "Aziz Oscar Romero", "Yoksullar için konuşan ve El Salvador iç savaşı sırasında şiddeti kınayan San Salvador başpiskoposu (1917-1980). Ayin yaparken vurularak öldürüldü; 2018'de aziz ilan edildi.", "El Salvador, adalet savunucuları, yoksullar"),
    ("March 25", "The Annunciation of the Lord", "Rab'bin Müjdelenmesi", "Melek Cebrail Meryem'e Tanrı'nın Oğlu'nu doğuracağını bildirir; Meryem 'Söylediğin gibi olsun' diye yanıt verir. Bayram, Noel'den dokuz ay öncesine denk gelir.", "Anneler, Tanrı'ya 'evet' diyenler"),
    ("March 26", "Saint Ludger", "Aziz Ludger", "Saksonya'da vaaz veren, Werden Manastırı'nı kuran ve Münster'in ilk piskoposu olan Frizyalı piskopos (yaklaşık 742-809). Charlemagne Saksonya misyonunu ona emanet etti.", "Misyonerler, Almanya"),
    ("March 27", "Saint Rupert of Salzburg", "Salzburglu Aziz Rupert", "Bavyera'da Salzburg Kilisesi'ni ve Aziz Peter Manastırı'nı kuran piskopos ve misyoner (yaklaşık 660-718). Bavyera ve Avusturya'nın havarisi olarak anılır.", "Salzburg, tuz madencileri"),
    ("March 28", "Pope Saint Sixtus III", "Papa Aziz Sixtus III", "432-440 arasında papa. Efes Konsili Meryem'in Tanrı'nın Anası olduğunu onayladıktan sonra Roma'da Santa Maria Maggiore Bazilikası'nı yaptırdı. Doğu ve Batı kiliseleri arasında barış için çalıştı.", "Barış yapıcılar, kilise inşa edenler"),
    ("March 29", "Saint Berthold of Calabria", "Kalabria'lı Aziz Berthold", "On ikinci yüzyılda küçük bir grup arkadaşıyla Karmel Dağı'na yerleşen haçlı ve münzevi. Geleneksel olarak Karmelit tarikatının ilk başı sayılır.", "Karmelitler, münzeviler"),
    ("March 31", "Saint Benjamin the Deacon", "Diyakoz Aziz Benjamin", "Hapisten çıktıktan sonra İncil'i vaaz etmeyi bırakmayı reddettiği için 424'te şehit edilen İranlı diyakoz. Cesur tanıklığı ve yumuşaklığı Doğu ve Batı kiliselerinde anılır.", "Diyakozlar, tehlikede doğruyu söyleyenler"),

    ("April 2", "Saint Francis of Paola", "Paola'lı Aziz Francis", "Alçakgönüllülük, tövbe ve sevgiye adanmış Minim kardeşleri kuran İtalyan münzevi (1416-1507). Krallara da yoksullara da öğüt verdi; denizcilerin koruyucusudur.", "Denizciler, Minim kardeşler"),
    ("April 3", "Saint Richard of Chichester", "Chichester'lı Aziz Richard", "Kraliyet muhalefetine rağmen sürüsüne sadakatle hizmet eden İngiliz piskopos (1197-1253). Yoksullara cömertçe verdi; 'Seni daha net tanımak, daha çok sevmek' duasıyla anılır.", "Piskoposlar, arabacılar, Mesih'i tanımak isteyenler"),
    ("April 4", "Saint Isidore of Seville", "Sevillalı Aziz Isidore", "Antik bilgiyi Orta Çağ'a koruyan bir ansiklopedi yazan İspanyol piskopos ve bilgin (yaklaşık 560-636). Kilise Doktoru ilan edildi.", "Bilginler, öğrenciler, internet"),
    ("April 5", "Saint Vincent Ferrer", "Aziz Vincent Ferrer", "Avrupa'yı dolaşarak vaaz veren, pek çok kişiyi dönüşüme çağıran İspanyol Dominikan (1350-1419). Batı Ayrılığı'nın sona ermesine yardım etti ve barış için çalıştı.", "Vaizler, inşaatçılar, uzlaştırıcılar"),
    ("April 6", "Blessed Michael Rua", "Mübarek Michael Rua", "Aziz John Bosco'nun Salezyenlerin başındaki ilk halefi (1837-1910). Tarikatı kıtalara yaydı ve gençlere neşeli hizmet ruhunu yaşattı.", "Gençler, Salezyenler"),
    ("April 7", "Saint John Baptist de La Salle", "Aziz John Baptist de La Salle", "Hıristiyan Okulları Kardeşleri'ni kuran ve modern eğitimi şekillendiren öğretim yöntemlerini geliştiren Fransız rahip (1651-1719). Servetini yoksul çocukları eğitmek için verdi.", "Öğretmenler, okul müdürleri"),
    ("April 8", "Saint Julie Billiart", "Aziz Julie Billiart", "Yıllarca süren felci yenip Namur Notre Dame Rahibeleri'ni kuran ve kızların eğitimine hayatını adayan Fransız rahibe (1751-1816). Tanrı'ya sevinçli güveniyle bilinir.", "Hastalar, öğretmenler, engelliler"),
    ("April 10", "Saint Fulbert of Chartres", "Chartres'lı Aziz Fulbert", "Katedralini yangından sonra yeniden inşa eden ve okulunu bir öğrenim merkezi yapan Chartres piskoposu (yaklaşık 960-1028). Mektuplar ve ilahiler yazdı, Meryem'e bağlılığı teşvik etti.", "Öğretmenler, inşaatçılar"),
    ("April 11", "Saint Stanislaus of Krakow", "Krakowlu Aziz Stanislaus", "Kralı haksızlığı için azarlayan ve ayin sırasında öldürülen Krakow piskoposu (1030-1079). Polonya'nın koruyucu azizidir; Kilise'nin ahlaki sesinin tanığıdır.", "Polonya, Krakow, adalet için konuşanlar"),
    ("April 12", "Saint Zeno of Verona", "Veronalı Aziz Zeno", "Açık ve yumuşak biçimde öğreten, pek çok kişiyi vaftiz eden ve yoksulları koruyan Verona piskoposu (ö. yaklaşık 371). Vaazları günümüze ulaşmıştır; iyi yürekli bir çobanı gösterir.", "Olta balıkçıları, piskoposlar"),
    ("April 13", "Pope Saint Martin I", "Papa Aziz Martin I", "Mesih'in iradesi hakkındaki bir hatayı kınayan, imparator tarafından tutuklanıp kötü muamele görerek Kırım'a sürülen papa (ö. 655). Şehit olarak ölen son papa olarak anılır.", "Hakikat uğruna acı çekenler"),
    ("April 14", "Saint Lidwina of Schiedam", "Schiedam'lı Aziz Lidwina", "Buz pateni kazasından sonra 38 yıl yatağa bağlı kalan Hollandalı kadın (1380-1433). Acılarını Mesih'inkilere kattı; sabır örneği ve birçok kişinin danışmanı oldu.", "Kronik hastalar, buz pateni yapanlar"),
    ("April 15", "Saint Damien of Molokai", "Molokai'li Aziz Damien", "Hawaii'de cüzzamlılarla yaşamak için gönüllü olan, evler ve kiliseler inşa eden Belçikalı rahip (1840-1889). Hastalığa kendisi yakalandı ve onlara hizmet ederken öldü.", "Cüzzamlılar, dışlanmışlar, Hawaii"),
    ("April 17", "Pope Saint Anicetus", "Papa Aziz Anicetus", "Aziz Polycarp ile Paskalya tarihini görüşen ve farklılıklara rağmen dostluğunu sürdüren ikinci yüzyıl Roma piskoposu. Yanlış öğretişe karşı sağlam durdu.", "Barış yapıcılar, birlik arayanlar"),
    ("April 18", "Saint Apollonius the Apologist", "Savunmacı Aziz Apollonius", "Hıristiyan imanını Senato önünde açıkça savunduğu için yaklaşık 185'te şehit edilen Romalı senatör. Mantıklı savunması onu erken dönem Hıristiyan entelektüel tanıklığının örneği yaptı.", "Hukukçular, imanı savunanlar"),
    ("April 19", "Pope Saint Leo IX", "Papa Aziz Leo IX", "Kiliseyi ıslah etmek, yozlaşmayla savaşmak ve din adamlarını yenilemek için yorulmadan çalışan Alman papa (1002-1054). Papa olarak Avrupa'yı çok gezdi.", "Reformcular, yolcular"),
    ("April 20", "Saint Agnes of Montepulciano", "Montepulciano'lu Aziz Agnes", "14 yaşında manastıra giren, 20 yaşında başrahibe olan İtalyan Dominikan (1268-1317). Bir manastır kurdu; derin duası ve şifa armağanıyla tanındı.", "Dua dolu başrahibeler, hastalar"),
    ("April 22", "Saints Soter and Caius", "Aziz Soter ve Aziz Caius", "Roma Kilisesi'ni zulümden geçiren ikinci ve üçüncü yüzyıl papaları. Soter Korint'e büyük şefkatle yazdı; Caius şiddetli sınavlar döneminde hizmet etti.", "Zor zamanlardaki papazlar"),
    ("April 24", "Saint Fidelis of Sigmaringen", "Sigmaringen'li Aziz Fidelis", "Avukatlıktan Kapuçin keşişliğine geçen, İsviçre'de Protestanlara vaaz veren ve bir kalabalık tarafından şehit edilen Alman (1577-1622). Yoksullara iyiliğiyle tanınırdı.", "Hukukçular, imanı savunanlar"),
    ("April 26", "Pope Saint Cletus", "Papa Aziz Cletus", "Roma piskoposu olarak Aziz Petrus'un erken dönem halefi; Ayin'in Roma Kanonu'nda anılır. Hakkında az şey bilinir ama Kilise onu bir havarisel baba olarak onurlandırır.", "Piskoposlar, havarisel ardıllık"),
    ("April 27", "Saint Zita of Lucca", "Lucca'lı Aziz Zita", "Hayatı boyunca tek bir aileye sadakatle hizmet eden ve aldığından yoksullara veren ev hizmetçisi (yaklaşık 1212-1272). Neşeli hizmeti onu sevilen biri yaptı.", "Ev işçileri, kâhyalar"),
    ("April 30", "Pope Saint Pius V", "Papa Aziz Pius V", "Trento Konsili reformlarını uygulayan, Roma Ayin Kitabı'nı standartlaştıran ve Tespih'i teşvik eden Dominikan papa (1504-1572). Sade yaşadı ve yoksullara baktı.", "Reformcular, Tespih'e bağlılık"),
]
